def permisos_casos(apps, schema_editor):
    """Concede el módulo de casos sociales sin restablecer permisos personalizados (como 0010)."""
    alias = schema_editor.connection.alias
    Group = apps.get_model('auth', 'Group')
    Permission = apps.get_model('auth', 'Permission')
    ContentType = apps.get_model('contenttypes', 'ContentType')
    reglas = {
        'Coordinador': ('view', 'add', 'change', 'delete'),
        'Delegado Municipal': ('view', 'add', 'change', 'delete'),
        'Operador / Funcionario': ('view', 'add', 'change'),
        'Consultor': ('view',),
    }
    ct, _ = ContentType.objects.using(alias).get_or_create(app_label='gestion', model='casosocial')
    permisos = {}
    for accion in ('view', 'add', 'change', 'delete'):
        permisos[accion], _ = Permission.objects.using(alias).get_or_create(
            content_type=ct, codename=f'{accion}_casosocial', defaults={'name': f'Can {accion} caso social'})
    for nombre, acciones in reglas.items():
        grupo = Group.objects.using(alias).filter(name=nombre).first()
        if grupo is not None:
            grupo.permissions.add(*(permisos[accion] for accion in acciones))


